// Constant time comparison: the loop always runs over the longer string and never stops early.
const sameText = (a, b) => {
  a = String(a ?? ''); b = String(b ?? '');
  let d = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) d |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return d === 0;
};

// Every entry point starts here: Stripe's webhook, the Retry webhook, the status calls from the native GoHighLevel
// workflows and the stuck run check. Settings are read and checked once; later nodes read them from this node. Tokens and secrets are not
// copied into the item: the nodes that need them read $env directly.
const S = v => String(v ?? '').trim();
const problems = [];
const num = (name, raw, def, lo, hi) => {
  const t = S(raw);
  if (!t) return def;
  const n = Number(t);
  if (!Number.isFinite(n) || n < lo || n > hi) { problems.push(`${name} must be a number from ${lo} to ${hi} (it is "${t}")`); return def; }
  return n;
};
const id = (name, raw) => {
  const t = S(raw);
  if (!t) problems.push(`${name} is empty`);
  else if (!/^[A-Za-z0-9_-]{4,64}$/.test(t)) problems.push(`${name} does not look like a GoHighLevel ID (letters and digits only)`);
  return t;
};
const secret = (name, raw, min) => { if (S(raw).length < min) problems.push(`${name} must be a random string of at least ${min} characters`); };
const url = (name, raw, def) => {
  const t = (S(raw) || def).replace(/\/+$/, '');
  if (!/^https?:\/\/[^\s/]+/i.test(t)) problems.push(`${name} must be a full URL that starts with https://`);
  return t;
};

const DEFAULT_VALUES = {
  businessName: 'Business Name', businessPhone: 'Business Phone', businessEmail: 'Business Email',
  businessAddress: 'Business Address', businessCity: 'Business City', businessState: 'Business State',
  businessPostalCode: 'Business Postal Code', businessCountry: 'Business Country', businessWebsite: 'Business Website',
  ownerFirstName: 'Owner First Name', ownerName: 'Owner Name', bookingLink: 'Booking Link',
};
const cfg = {
  companyId: id('GHL_COMPANY_ID', $env.GHL_COMPANY_ID),
  homeLocationId: id('GHL_HOME_LOCATION_ID', $env.GHL_HOME_LOCATION_ID),
  pipelineId: id('GHL_ONBOARDING_PIPELINE_ID', $env.GHL_ONBOARDING_PIPELINE_ID),
  stageId: id('GHL_ONBOARDING_STAGE_ID', $env.GHL_ONBOARDING_STAGE_ID),
  newClientTag: (S($env.NEW_CLIENT_TAG) || 'new-client').toLowerCase(),
  plans: {},
  planKey: S($env.STRIPE_PLAN_METADATA_KEY) || 'onboarding_plan',
  businessFieldKey: S($env.STRIPE_BUSINESS_FIELD_KEY) || 'businessname',
  websiteFieldKey: S($env.STRIPE_WEBSITE_FIELD_KEY) || 'website',
  tolerance: num('STRIPE_TOLERANCE_SECONDS', $env.STRIPE_TOLERANCE_SECONDS, 300, 30, 600),
  clientTimezone: S($env.CLIENT_TIMEZONE) || 'America/New_York',
  bookingCalendar: S($env.CLIENT_BOOKING_CALENDAR) || 'Discovery Call',
  customValueNames: { ...DEFAULT_VALUES },
  appUrl: url('GHL_APP_URL', $env.GHL_APP_URL, 'https://app.gohighlevel.com'),
  bookingBaseUrl: url('GHL_BOOKING_BASE_URL', $env.GHL_BOOKING_BASE_URL, 'https://api.leadconnectorhq.com/widget/booking'),
  ledgerTableId: S($env.LEDGER_TABLE_ID),
  apiMaxAttempts: num('API_MAX_ATTEMPTS', $env.API_MAX_ATTEMPTS, 3, 1, 5),
  retryBaseSeconds: num('RETRY_BASE_SECONDS', $env.RETRY_BASE_SECONDS, 2, 0.5, 30),
  rateLimitWait: num('GHL_RATE_LIMIT_WAIT_SECONDS', $env.GHL_RATE_LIMIT_WAIT_SECONDS, 10, 1, 120),
  lockWaitSeconds: num('LOCK_WAIT_SECONDS', $env.LOCK_WAIT_SECONDS, 5, 0, 9),
  setupWaitSeconds: num('SETUP_WAIT_SECONDS', $env.SETUP_WAIT_SECONDS, 180, 0, 600),
  setupPollSeconds: num('SETUP_POLL_SECONDS', $env.SETUP_POLL_SECONDS, 10, 1, 60),
  appId: S($env.GHL_APP_ID),
  stuckMinutes: num('STUCK_CHECK_MINUTES', $env.STUCK_CHECK_MINUTES, 30, 20, 1440),
  lockMinutes: 15,
};
if (!/^[A-Za-z0-9_-]{4,64}$/.test(S($env.GHL_APP_ID))) problems.push('GHL_APP_ID must be the ID of your HighLevel agency app (Marketplace developer portal > your app)');
if (!S($env.GHL_HOME_TOKEN)) problems.push("GHL_HOME_TOKEN is empty (the token of the agency's own sub-account)");
if (!/^whsec_\S{8,}$/.test(S($env.STRIPE_WEBHOOK_SECRET))) problems.push("STRIPE_WEBHOOK_SECRET must be the endpoint's signing secret from Stripe (it starts with whsec_)");
secret('RETRY_SECRET', $env.RETRY_SECRET, 24);
secret('GHL_STATUS_SECRET', $env.GHL_STATUS_SECRET, 24);
if (!/^https:\/\/\S+$/.test(S($env.SLACK_WEBHOOK_URL)) && !/^http:\/\/\S+$/.test(S($env.SLACK_WEBHOOK_URL))) problems.push('SLACK_WEBHOOK_URL must be a Slack incoming webhook URL');
if (!cfg.ledgerTableId) problems.push('LEDGER_TABLE_ID is empty (the ID of the n8n data table that keeps the onboarding ledger)');
if (!/^[A-Za-z0-9_-]{1,40}$/.test(cfg.planKey)) problems.push('STRIPE_PLAN_METADATA_KEY must be a metadata key such as onboarding_plan');
if (!/^[A-Za-z0-9]{1,200}$/.test(cfg.businessFieldKey) || !/^[A-Za-z0-9]{1,200}$/.test(cfg.websiteFieldKey)) problems.push('STRIPE_BUSINESS_FIELD_KEY and STRIPE_WEBSITE_FIELD_KEY must be Checkout custom field keys (letters and digits only)');
if (!/^[a-z0-9][a-z0-9 _-]{0,49}$/.test(cfg.newClientTag)) problems.push('NEW_CLIENT_TAG must be a short tag such as new-client');
try { new Intl.DateTimeFormat('en-US', { timeZone: cfg.clientTimezone }); } catch (e) { problems.push(`CLIENT_TIMEZONE "${cfg.clientTimezone}" is not a valid time zone`); }
let plans = null;
try { plans = JSON.parse(S($env.PLAN_SNAPSHOTS) || 'null'); } catch (e) { plans = null; }
let plansOk = !!plans && typeof plans === 'object' && !Array.isArray(plans) && Object.keys(plans).length > 0;
if (plansOk) {
  for (const [key, v] of Object.entries(plans)) {
    const snap = typeof v === 'string' ? v : (v && v.snapshotId);
    if (!/^[A-Za-z0-9_-]{4,64}$/.test(String(snap || ''))) { plansOk = false; break; }
    cfg.plans[key.trim().toLowerCase()] = { key: key.trim().toLowerCase(), snapshotId: String(snap), label: S(v && v.label) || key.trim() };
  }
}
if (!plansOk) problems.push('PLAN_SNAPSHOTS must be JSON that maps each plan to its snapshot, such as {"launch": {"snapshotId": "abc123", "label": "Launch"}}');
if (S($env.CUSTOM_VALUE_NAMES)) {
  let over = null;
  try { over = JSON.parse(S($env.CUSTOM_VALUE_NAMES)); } catch (e) { over = null; }
  const valid = !!over && typeof over === 'object' && !Array.isArray(over) && Object.entries(over).every(([k, v]) => k in DEFAULT_VALUES && typeof v === 'string');
  if (!valid) problems.push(`CUSTOM_VALUE_NAMES must be JSON that renames these keys: ${Object.keys(DEFAULT_VALUES).join(', ')}`);
  else for (const [k, v] of Object.entries(over)) { if (v.trim()) cfg.customValueNames[k] = v.trim(); else delete cfg.customValueNames[k]; }   // "" switches one off
}
const lower = Object.values(cfg.customValueNames).map(v => v.toLowerCase());
if (new Set(lower).size !== lower.length) problems.push('Two custom values in CUSTOM_VALUE_NAMES have the same name');

const trigger = $('Stripe Webhook').isExecuted ? 'stripe' : $('Retry Onboarding').isExecuted ? 'retry' : $('GHL Status').isExecuted ? 'status' : 'sweep';
const out = { cfg, trigger, route: trigger };
if (problems.length) {
  out.route = trigger === 'sweep' ? 'sweep-bad-settings' : 'bad-settings';   // a scheduled run has nobody to answer
  out.stop = 'settings';
  out.stopMessage = 'Settings are not valid, so nothing was done. ' + problems.join('. ') + '.';
  // Stripe and GoHighLevel only see a plain 500 (Stripe tries the event again later); the Retry caller gets the list.
  out.respond = trigger === 'retry'
    ? { status: 500, body: { started: false, error: 'settings', problems } }
    : { status: 500, body: { received: false, error: 'settings' } };
}
// The raw body of a Stripe call stays attached as binary data, so the signature can be checked over the exact bytes.
return [{ json: out, binary: $input.first().binary }];

// Stripe signs every delivery. The Stripe-Signature header carries t=<unix time> and one v1=<hex HMAC SHA-256> for
// each active signing secret (two while a secret is being rolled); other schemes such as v0 are ignored. The signed
// text is the timestamp, a dot and the raw body exactly as it arrived, so the body is read from the raw bytes and
// never from n8n's parsed JSON.
const headers = $('Stripe Webhook').first().json.headers || {};
const header = String(headers['stripe-signature'] || '');
let raw = '';
try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) { raw = ''; }
let t = '';
const v1 = [];
for (const part of header.split(',')) {
  const i = part.indexOf('=');
  if (i < 1) continue;
  const k = part.slice(0, i).trim(), v = part.slice(i + 1).trim();
  if (k === 't') t = v;
  else if (k === 'v1' && /^[0-9a-fA-F]{64}$/.test(v)) v1.push(v.toLowerCase());
}
const problem = !header ? 'the request has no Stripe-Signature header'
  : !/^\d{9,11}$/.test(t) ? 'the Stripe-Signature header has no valid timestamp'
  : !v1.length ? 'the Stripe-Signature header has no v1 signature'
  : !raw ? 'the request body is empty' : '';
return [{ json: { t, v1, raw, problem, signedPayload: problem ? 'none' : `${t}.${raw}` } }];

// Constant time comparison: the loop always runs over the longer string and never stops early.
const sameText = (a, b) => {
  a = String(a ?? ''); b = String(b ?? '');
  let d = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) d |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return d === 0;
};

// Verifies the signature (constant time, every v1 value), then the timestamp against STRIPE_TOLERANCE_SECONDS, then
// reads the event from the raw body. Only a paid Checkout Session for an onboarding plan goes on. Everything else gets
// a 2xx at once, so Stripe does not send it again; a bad signature gets 400 and an alert.
const cfg = $('Load Settings').first().json.cfg;
const sig = $input.first().json;
const S = v => String(v ?? '').trim();
const ok = body => ({ status: 200, body: { received: true, ...body } });
let problem = sig.problem;
if (!problem) {
  let match = false;
  for (const candidate of sig.v1) if (sameText(candidate, sig.expected)) match = true;
  const age = Math.round(Date.now() / 1000 - Number(sig.t));
  if (!match) problem = 'no v1 signature in the Stripe-Signature header matches STRIPE_WEBHOOK_SECRET';
  else if (Math.abs(age) > cfg.tolerance) problem = `the signed timestamp is ${age} seconds old, outside the ${cfg.tolerance} second tolerance (a replayed request, or a clock that is off)`;
}
if (problem) {
  return [{ json: { route: 'refused', stop: 'signature', respond: { status: 400, body: { received: false, error: 'invalid signature' } },
    stopMessage: `Refused a call to the Stripe webhook: ${problem}. Nothing was done. If Stripe sent it, check that STRIPE_WEBHOOK_SECRET is the signing secret of this endpoint.` } }];
}
let event = null;
try { event = JSON.parse(sig.raw); } catch (e) { event = null; }
if (!event || !['event', 'v2.core.event'].includes(event.object) || !/^evt_[A-Za-z0-9]+$/.test(S(event.id)) || !S(event.type)) {
  return [{ json: { route: 'refused', stop: 'signature', respond: { status: 400, body: { received: false, error: 'not a Stripe event' } },
    stopMessage: 'Refused a call to the Stripe webhook: the signature was valid but the body is not a Stripe event object. Nothing was done.' } }];
}
const HANDLED = ['checkout.session.completed', 'checkout.session.async_payment_succeeded'];
const type = S(event.type).replace(/^v1\./, '');   // thin events name v1 resources "v1.<type>"
const base = { eventId: event.id, eventType: type, livemode: !!event.livemode };
if (!HANDLED.includes(type)) return [{ json: { ...base, route: 'ignore', respond: ok({ ignored: `event type ${type} is not used` }) } }];
const s = (event.data && event.data.object) || null;
if (!s || s.object !== 'checkout.session') {
  // A thin event (only an ID, no data) cannot be fulfilled from the payload. Stripe would send it again unchanged, so
  // it gets a 200 and an alert that says how to fix the event destination.
  return [{ json: { ...base, route: 'refused', stop: 'payload', respond: ok({ ignored: 'no Checkout Session in the payload' }),
    stopMessage: `Stripe event ${event.id} (${type}) arrived without the Checkout Session in it, so nobody was onboarded. Set the event destination's payload style to snapshot (full objects) in Stripe, then resend the event from the Stripe Dashboard.` } }];
}
const plan = S((s.metadata || {})[cfg.planKey]).toLowerCase();
if (!plan) return [{ json: { ...base, route: 'ignore', respond: ok({ ignored: `not an onboarding purchase (no ${cfg.planKey} metadata)` }) } }];
if (s.mode === 'setup') return [{ json: { ...base, route: 'ignore', respond: ok({ ignored: 'setup mode session' }) } }];
if (s.payment_status === 'unpaid' || (s.status && s.status !== 'complete')) {
  return [{ json: { ...base, route: 'ignore', respond: ok({ ignored: 'payment not finished yet; waiting for checkout.session.async_payment_succeeded' }) } }];
}

// The client, from the Checkout Session: the business name from a custom field (or Checkout's business name), the
// person from customer_details, the website from an optional custom field.
const field = key => (s.custom_fields || []).find(f => f && f.key === key);
const fieldValue = f => !f ? '' : S(f.type === 'dropdown' ? (f.dropdown || {}).value : f.type === 'numeric' ? (f.numeric || {}).value : (f.text || {}).value);
const cd = s.customer_details || {};
const ci = s.collected_information || {};
const addr = cd.address || {};
const person = S(cd.individual_name) || S(cd.name) || S(ci.individual_name);
const parts = person.split(/\s+/).filter(Boolean);
let website = fieldValue(field(cfg.websiteFieldKey));
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
const client = {
  business: (fieldValue(field(cfg.businessFieldKey)) || S(cd.business_name) || S(ci.business_name)).replace(/\s+/g, ' ').slice(0, 100),
  name: person, firstName: parts[0] || '', lastName: parts.slice(1).join(' '),
  email: S(cd.email || s.customer_email).toLowerCase(),
  phone: S(cd.phone),
  address1: [S(addr.line1), S(addr.line2)].filter(Boolean).join(', '),
  city: S(addr.city), state: S(addr.state), postalCode: S(addr.postal_code), country: S(addr.country).toUpperCase(),
  website,
};
return [{ json: { ...base, route: 'process', mode: 'stripe', sessionId: S(s.id), planKey: plan, client,
  amount: { total: Number.isFinite(s.amount_total) ? s.amount_total : null, currency: S(s.currency).toUpperCase() },
  paymentIntent: S(typeof s.payment_intent === 'string' ? s.payment_intent : (s.payment_intent || {}).id),
  customerId: S(typeof s.customer === 'string' ? s.customer : (s.customer || {}).id) } }];

// Constant time comparison: the loop always runs over the longer string and never stops early.
const sameText = (a, b) => {
  a = String(a ?? ''); b = String(b ?? '');
  let d = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) d |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return d === 0;
};

// POST /webhook/ghl-onboarding-retry with the X-Run-Secret header and {"eventId": "evt_..."}: continues an onboarding
// from the last step the ledger recorded. An empty RETRY_SECRET refuses every call (Load Settings insists on one).
const req = $('Retry Onboarding').first().json;
const given = String((req.headers || {})['x-run-secret'] || '');
if (!sameText(given, String($env.RETRY_SECRET || '').trim()) || !given) {
  return [{ json: { route: 'refused', stop: 'secret', respond: { status: 401, body: { started: false, error: 'unauthorized' } },
    stopMessage: 'Refused a call to the Retry webhook: wrong or missing X-Run-Secret header. Nothing was done.' } }];
}
const eventId = String((req.body || {}).eventId || '').trim();
if (!/^evt_[A-Za-z0-9]+$/.test(eventId)) {
  return [{ json: { route: 'bad-request', respond: { status: 400, body: { started: false, error: 'send {"eventId": "evt_..."} with the Stripe event ID from the alert' } } } }];
}
return [{ json: { route: 'process', mode: 'retry', eventId, sessionId: '' } }];

// Only one onboarding runs at a time, so two deliveries of the same event (Stripe can send one twice, even at the
// same moment) or a retry during a run can never create two sub-accounts. The lock is a ledger row (key __run_lock__):
// "attempts" holds the time it runs out (epoch milliseconds), "note" the execution that holds it.
return [{ json: { ...$input.first().json, lockStartedAt: Date.now() } }];

// Takes the lock with a conditional update on the value just read, so two runs cannot both take it. A run that waits
// longer than LOCK_WAIT_SECONDS answers 503 to Stripe (Stripe sends the event again later) or 409 to a Retry call.
// A lock left by a run that crashed runs out after 15 minutes.
const cfg = $('Load Settings').first().json.cfg;
const ctx = $('Begin Lock').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.key === '__run_lock__');
const now = Date.now();
const runId = String($execution.id);
const base = { until: now + cfg.lockMinutes * 60000, runId };
// Taking a free lock only fails when two runs try at the same moment, and the next look settles that. If it keeps
// failing (a lock row edited by hand, "attempts" not a Number column), the run stops with an alert instead of looping.
const elapsed = now - ctx.lockStartedAt;
const stuck = elapsed > (cfg.lockWaitSeconds + 10) * 1000
  ? [{ json: { ...base, route: 'stuck', error: `the run lock (the ledger row with the key __run_lock__) could not be taken for ${Math.round(elapsed / 1000)} seconds although no run holds it. Check that row: "attempts" must be a number (0 when free) in a Number column` } }]
  : null;
if (!rows.length) return stuck || [{ json: { ...base, route: 'create' } }];
const busy = rows.find(r => Number(r.attempts) > now && String(r.note) !== runId);
if (!busy) return stuck || [{ json: { ...base, route: 'take', expect: Number(rows[0].attempts) || 0 } }];
if (now - ctx.lockStartedAt < cfg.lockWaitSeconds * 1000) return [{ json: { ...base, route: 'wait' } }];
const respond = ctx.mode === 'stripe'
  ? { status: 503, body: { received: false, error: 'busy, another onboarding is running; please send the event again' } }
  : { status: 409, body: { started: false, error: 'busy, another onboarding is running; try again in a minute' } };
return [{ json: { ...base, route: 'busy', heldBy: busy.note, respond } }];

// Another run holds the lock (or two runs created it at the same moment): wait a second and look again.
await new Promise(r => setTimeout(r, 1000));
return [{ json: { waited: true } }];

// n8n error objects (from an error output) carry message, description and sometimes httpCode
const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e.slice(0, 300);
  const parts = [e.httpCode, e.message, e.description].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(String);
  return [...new Set(parts)].join(' - ').replace(/\s+/g, ' ').slice(0, 300);
};

// The ledger (n8n data table) could not be read or written before anything was created. Stripe gets a 500 and sends
// the event again later; the alert names the problem.
const ctx = $('Begin Lock').first().json;
const e = $input.first().json.error;
return [{ json: { respond: ctx.mode === 'stripe' ? { status: 500, body: { received: false, error: 'ledger unavailable' } } : { status: 500, body: { started: false, error: 'ledger unavailable' } },
  stopMessage: `The onboarding ledger (n8n data table LEDGER_TABLE_ID) could not be used${errText(e) ? ': ' + errText(e) : ''}. Nothing was created for Stripe event ${ctx.eventId}; ${ctx.mode === 'stripe' ? 'Stripe sends it again later' : 'try the retry again'}.` } }];

const ORDER = ['subaccount', 'user', 'customValues', 'contact', 'opportunity', 'note', 'tag', 'slack'];
const LABEL = {
  subaccount: 'create the sub-account from the snapshot', user: 'create the admin user', customValues: 'fill the custom values',
  contact: 'add the client to the agency CRM', opportunity: 'put the opportunity in the Onboarding stage', note: 'add the onboarding note',
  tag: 'add the new client tag', slack: 'post the Slack summary',
};

// Decides what to do with this event now that the lock is held. The ledger has one row per Stripe event (key = event
// ID). A finished event, or a second event for a session that is already onboarded, is a duplicate. Anything else
// starts or continues the onboarding from the steps the ledger recorded. The plan and the client details are checked
// on every run, so fixing PLAN_SNAPSHOTS and sending a retry is enough to get a held event going.
const cfg = $('Load Settings').first().json.cfg;
const ctx = $('Begin Lock').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.key && r.key !== '__run_lock__');
const parse = t => { try { const v = JSON.parse(t || '{}'); return v && typeof v === 'object' ? v : {}; } catch (e) { return {}; } };
const own = rows.filter(r => r.key === ctx.eventId).sort((a, b) => Number(a.id) - Number(b.id))[0] || null;
const other = rows.find(r => r.key !== ctx.eventId && ctx.sessionId && r.sessionId === ctx.sessionId && r.status !== 'ignored');
const stripe = ctx.mode === 'stripe';
const handled = (status, body, note) => [{ json: { route: 'handled', respond: { status, body }, note } }];

if (stripe && own && own.status === 'done') return handled(200, { received: true, duplicate: true }, `event ${ctx.eventId} was onboarded before`);
if (stripe && other) return handled(200, { received: true, duplicate: true }, `session ${ctx.sessionId} is already handled by event ${other.key}`);
if (!stripe && !own) return handled(404, { started: false, error: 'no onboarding with this event ID in the ledger' }, 'unknown event');
if (!stripe && own.status === 'done') return handled(409, { started: false, error: 'this onboarding is already finished' }, 'already finished');

const data = own ? parse(own.data) : {
  planKey: ctx.planKey, client: ctx.client, amount: ctx.amount, sessionId: ctx.sessionId, paymentIntent: ctx.paymentIntent,
  customerId: ctx.customerId, livemode: ctx.livemode, eventType: ctx.eventType, receivedAt: new Date().toISOString(),
};
const steps = own ? parse(own.steps) : {};
const client = data.client || {};
const plan = cfg.plans[String(data.planKey || '').toLowerCase()];
const problems = [];
if (!plan) problems.push(`the plan "${data.planKey}" from the checkout is not in PLAN_SNAPSHOTS`);
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(client.email || '')) problems.push('the checkout has no valid email address');
if (!client.business) problems.push(`the checkout has no business name (Checkout custom field "${cfg.businessFieldKey}" or Checkout's business name)`);
if (!client.firstName) problems.push('the checkout has no customer name');
const req = $('Retry Onboarding').isExecuted ? ($('Retry Onboarding').first().json.body || {}) : {};
const retryOptions = {
  createSubAccount: req.createSubAccount === true,
  subAccountId: /^[A-Za-z0-9]{4,64}$/.test(String(req.subAccountId || '')) ? String(req.subAccountId) : '',
};
const firstOpen = ORDER.find(s => !(steps[s] && steps[s].done)) || 'slack';
const ledgerRow = {
  key: ctx.eventId, sessionId: data.sessionId || '', status: problems.length ? 'needs_review' : 'in_progress', plan: String(data.planKey || ''),
  business: client.business || '', email: client.email || '', locationId: own ? own.locationId || '' : '', userId: own ? own.userId || '' : '',
  contactId: own ? own.contactId || '' : '', opportunityId: own ? own.opportunityId || '' : '', steps: JSON.stringify(steps),
  attempts: (own ? Number(own.attempts) || 0 : 0) + 1, note: problems.length ? 'Needs a person: ' + problems.join('; ') : `Run ${$execution.id} working`,
  data: JSON.stringify(data), kickoff: own ? own.kickoff || '' : '', changedAt: new Date().toISOString(),
};
const respond = problems.length
  ? (stripe ? { status: 200, body: { received: true } } : { status: 422, body: { started: false, error: 'needs review', problems } })
  : (stripe ? { status: 200, body: { received: true } } : { status: 202, body: { started: true, continuesWith: LABEL[firstOpen] } });
return [{ json: {
  route: problems.length ? 'needs-review' : 'start', respond, ledgerRow, problems, retryOptions, resumed: !!own,
  eventId: ctx.eventId, mode: ctx.mode, data, steps, plan: plan || null,
} }];

// The working state of this run. "steps" is what the ledger keeps: each finished step with the IDs it created.
// "run" only lives in this execution (current step, phase, tries, the sub-account token).
const p = $input.first().json;
return [{ json: {
  eventId: p.eventId, mode: p.mode, data: p.data, client: p.data.client, plan: p.plan, steps: p.steps, retryOptions: p.retryOptions,
  resumed: p.resumed, slackWasDone: !!(p.steps.slack && p.steps.slack.done),
  run: { step: null, phase: null, tries: 1, waited: 0, issues: [], softFailed: [], started: Date.now() },
} }];

const ORDER = ['subaccount', 'user', 'customValues', 'contact', 'opportunity', 'note', 'tag', 'slack'];
const LABEL = {
  subaccount: 'create the sub-account from the snapshot', user: 'create the admin user', customValues: 'fill the custom values',
  contact: 'add the client to the agency CRM', opportunity: 'put the opportunity in the Onboarding stage', note: 'add the onboarding note',
  tag: 'add the new client tag', slack: 'post the Slack summary',
};

const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Runs the onboarding one step at a time, in order:
//   sub-account from the plan's snapshot > admin user > custom values (by name) > contact in the agency sub-account >
//   opportunity in the Onboarding stage > note > new client tag (starts the native GoHighLevel workflow) > Slack.
// Every call goes out through Build Call and comes back here with its reply. A finished step is saved to the ledger
// (with the IDs it created) before the next one starts, so a retry continues where a run stopped. Creates are only
// sent after a lookup found nothing, so a retry adopts what an earlier run created instead of making a second one.
// A step that keeps failing ends the run, except the custom values: a value the snapshot lacks, or a failure while
// filling them, is listed for a person and the run carries on, so the welcome email is never held up by it.
const cfg = $('Load Settings').first().json.cfg;
const ctx = JSON.parse(JSON.stringify($input.first().json));
const reply = ctx.reply || null;
delete ctx.reply; delete ctx.call; delete ctx.route;
const st = ctx.steps, run = ctx.run, c = ctx.client, plan = ctx.plan;
const S = v => String(v ?? '').trim();
const norm = v => S(v).toLowerCase().replace(/\s+/g, ' ');
const sleep = s => new Promise(r => setTimeout(r, s * 1000));
const now = () => new Date().toISOString();
const loc = () => (st.subaccount || {}).locationId;
const go = (route, extra = {}) => [{ json: { ...ctx, route, ...extra } }];
const ask = (kind, spec = {}) => { run.phase = kind; return go('call', { call: { kind, attempt: 1, ...spec } }); };
const save = () => go('save');
const done = patch => { st[run.step] = { ...(st[run.step] || {}), ...patch, done: true, at: now() }; delete st[run.step].error; delete run.token; run.step = null; return save(); };
const fail = (reason, hint = '') => { run.failure = { step: run.step, reason, hint }; return go('finish'); };
const soft = (patch, reason) => {
  st[run.step] = { ...(st[run.step] || {}), ...patch, done: false, error: reason, at: now() };
  run.softFailed.push(run.step); run.issues.push(reason); delete run.token; run.step = null; return save();
};
const why = r => r.explain || `GoHighLevel answered ${r.status}`;
const values = () => ({
  businessName: c.business, businessPhone: c.phone, businessEmail: c.email, businessAddress: c.address1, businessCity: c.city,
  businessState: c.state, businessPostalCode: c.postalCode, businessCountry: c.country, businessWebsite: c.website,
  ownerFirstName: c.firstName, ownerName: c.name, bookingLink: run.bookingLink || '',
});
const amountText = () => ctx.data.amount && ctx.data.amount.total !== null
  ? `${ctx.data.amount.currency} ${(ctx.data.amount.total / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : 'amount unknown';
const locUrl = id => `${cfg.appUrl}/v2/location/${id}/dashboard`;
const contactUrl = id => `${cfg.appUrl}/v2/location/${cfg.homeLocationId}/contacts/detail/${id}`;
const marker = `[onboarding ${ctx.eventId}]`;

// ---------------------------------------------------------------- a reply came back
if (reply) {
  const r = reply;
  const k = run.phase;
  if (run.step === 'subaccount') {
    if (k === 'findLocation' || k === 'listLocations') {
      if (!r.ok) return fail(why(r));
      const list = (r.body && r.body.locations) || [];
      // Only a sub-account with the client's name AND email is taken as this client's. A name alone can belong to another
      // client (two businesses can share a name, and HighLevel does not document the search's email filter); using it
      // would put this client's login and details into someone else's sub-account.
      const hit = list.find(l => norm(l.name) === norm(c.business) && norm(l.email) === norm(c.email));
      if (hit) return done({ locationId: hit.id, name: hit.name, adopted: true, pending: null });
      const pending = (st.subaccount || {}).pending;
      if (pending && k === 'findLocation') return ask('listLocations', { query: { companyId: cfg.companyId, limit: '100', order: 'desc' } });
      // A person's {"createSubAccount": true} covers one create. If that create loses its answer too, a person decides again.
      if (pending && !(ctx.retryOptions.createSubAccount && !run.createAllowedUsed)) {
        const same = list.filter(l => norm(l.name) === norm(c.business)).slice(0, 5);
        const seen = same.length
          ? `. ${same.length > 1 ? 'Sub-accounts with that name exist' : 'A sub-account with that name exists'} (${same.map(l => `ID ${l.id}, ${S(l.email) ? 'email ' + S(l.email) : 'no email'}`).join('; ')}), but the workflow cannot tell whether ${same.length > 1 ? 'one of them' : 'it'} is this client's`
          : ' and no sub-account with that name was found';
        return fail(`a create call for the sub-account "${c.business}" was sent at ${pending.at}, but its answer never arrived${seen}`,
          `Look in Agency view > Sub-Accounts. If this client's "${c.business}" is there, send the retry with {"eventId": "${ctx.eventId}", "subAccountId": "<its ID>"} to use it. If it is not there, send {"eventId": "${ctx.eventId}", "createSubAccount": true} to create it`);
      }
      if (pending) run.createAllowedUsed = true;
      st.subaccount = { ...(st.subaccount || {}), pending: { at: now() } };
      run.phase = 'create';
      return save();
    }
    if (k === 'getLocation') {
      const l = r.ok ? (r.body.location || r.body) : null;
      if (!l || l.companyId !== cfg.companyId) return fail(`the sub-account ${ctx.retryOptions.subAccountId} from the retry could not be used: ${r.ok ? 'it belongs to another agency' : why(r)}`);
      return done({ locationId: l.id, name: l.name, adopted: true, pending: null });
    }
    if (k === 'createLocation') {
      if (r.ok && r.body && r.body.id) return done({ locationId: r.body.id, name: r.body.name || c.business, adopted: false, pending: null, snapshotId: plan.snapshotId });
      if (r.retryable && r.kind !== 'throttled') {
        // The create may have gone through even though no answer came back. Look it up; it is never sent again blindly.
        run.tries++; await sleep(cfg.retryBaseSeconds * 2);
        return ask('findLocation', { query: { companyId: cfg.companyId, email: c.email, limit: '100' } });
      }
      // A refused create (4xx, or 429 after every wait) created nothing, so the next try may create again without asking a person.
      st.subaccount = { ...(st.subaccount || {}), pending: null };
      return fail(why(r), r.status === 401 || r.status === 403 ? 'Creating sub-accounts through the API needs the Agency Pro plan and the locations.write scope on the agency app' : '');
    }
  }
  if (run.step === 'user') {
    if (k === 'findUser') {
      if (!r.ok) return fail(why(r));
      const u = ((r.body && r.body.users) || []).find(x => norm(x.email) === norm(c.email) && !x.deleted);
      if (u) {
        const access = ((u.roles || {}).locationIds || []).includes(loc());
        if (access) return done({ userId: u.id, adopted: true });
        return fail(`a HighLevel user with the email ${c.email} already exists (user ${u.id}) but cannot open the new sub-account`,
          `Give that user access to the sub-account in Agency view > Team (or ask the client for another email), then send the retry; the user is then picked up as it is`);
      }
      return ask('createUser', { body: { companyId: cfg.companyId, firstName: c.firstName, lastName: c.lastName || '-', email: c.email, type: 'account', role: 'admin', locationIds: [loc()], ...(c.phone ? { phone: c.phone } : {}) } });
    }
    if (k === 'createUser') {
      if (r.ok && r.body && r.body.id) return done({ userId: r.body.id, adopted: false });
      if (r.retryable && run.tries < cfg.apiMaxAttempts) { run.tries++; await sleep(cfg.retryBaseSeconds * 2); return ask('findUser', { query: { companyId: cfg.companyId, query: c.email, limit: '25' } }); }
      return fail(why(r));
    }
  }
  if (run.step === 'customValues') {
    if (k === 'snapshotStatus') {
      // Snapshots load in the background after the sub-account is created; custom values can still be "pending".
      const d = r.ok ? ((r.body || {}).data || {}) : {};
      const list = v => Array.isArray(v) ? v.join(',') : String(v || '');
      const busy = r.ok && /process|pending|progress|queue/i.test(String(d.status || '')) && !/custom_values/.test(list(d.completed));
      if (busy && run.waited < cfg.setupWaitSeconds) {
        await sleep(cfg.setupPollSeconds); run.waited += cfg.setupPollSeconds;
        return ask('snapshotStatus', { snapshotId: plan.snapshotId, locationId: loc(), query: { companyId: cfg.companyId } });
      }
      if (busy) return soft({}, `the ${plan.label} snapshot was still loading into the sub-account after ${run.waited} seconds, so no custom value was filled yet`);
      // HighLevel documents this endpoint for snapshot pushes. When it gives no status, the custom values are checked instead.
      run.snapshotDone = r.ok && !!S(d.status);
      if (!r.ok) run.issues.push(`the snapshot status could not be read (${why(r)}), so the workflow waited for the custom values to appear instead`);
      return ask('appInstalled', { query: { companyId: cfg.companyId, appId: cfg.appId, locationId: loc(), isInstalled: 'true' } });
    }
    if (k === 'appInstalled') {
      // A sub-account token only exists once the agency app is installed on the sub-account. With "all sub-accounts"
      // chosen at install time HighLevel installs it on new ones by itself, which can take a moment.
      const found = r.ok && ((r.body || {}).locations || []).some(l => (l._id || l.id) === loc() && l.isInstalled !== false);
      if (r.ok && !found && run.waited < cfg.setupWaitSeconds) {
        await sleep(cfg.setupPollSeconds); run.waited += cfg.setupPollSeconds;
        return ask('appInstalled', { query: { companyId: cfg.companyId, appId: cfg.appId, locationId: loc(), isInstalled: 'true' } });
      }
      if (r.ok && !found) return soft({}, `the agency app is not installed on the new sub-account (checked for ${run.waited} seconds), so no custom value was filled. Install the app on it, or reinstall the app with "all sub-accounts" so new ones get it, then send the retry`);
      if (!r.ok) run.issues.push(`could not check whether the agency app is installed on the sub-account (${why(r)}); asked for its token anyway`);
      return ask('locationToken', { form: { companyId: cfg.companyId, locationId: loc() } });
    }
    if (k === 'locationToken') {
      if (!r.ok || !r.body || !r.body.access_token) return soft({}, `no token for the new sub-account (${r.ok ? 'the answer had no access_token' : why(r)}), so no custom value was filled. The agency app needs the oauth.write scope and must be installed on the sub-account`);
      run.token = r.body.access_token;
      return ask('listCustomValues', { locationId: loc(), token: run.token });
    }
    if (k === 'listCustomValues') {
      if (!r.ok) return soft({}, `the custom values of the sub-account could not be read: ${why(r)}`);
      const found = (r.body && r.body.customValues) || [];
      const ours = new Set(Object.values(cfg.customValueNames).map(norm));
      if (!run.snapshotDone && !found.some(x => ours.has(norm(x.name))) && run.waited < cfg.setupWaitSeconds) {
        // None of the custom values is there yet and the snapshot status did not confirm the load: it may still be loading.
        await sleep(cfg.setupPollSeconds); run.waited += cfg.setupPollSeconds;
        return ask('listCustomValues', { locationId: loc(), token: run.token });
      }
      run.cvList = found;
      if (cfg.customValueNames.bookingLink) return ask('listCalendars', { locationId: loc(), token: run.token, query: { locationId: loc() } });
    }
    if (k === 'listCalendars') {
      if (!r.ok) return soft({}, `the calendars of the sub-account could not be read: ${why(r)}`);
      const cal = ((r.body && r.body.calendars) || []).find(x => norm(x.name) === norm(cfg.bookingCalendar));
      if (cal) run.bookingLink = `${cfg.bookingBaseUrl}/${cal.id}`;
      else run.issues.push(`the snapshot has no calendar named "${cfg.bookingCalendar}", so "${cfg.customValueNames.bookingLink}" was left as it is`);
    }
    if (k === 'listCustomValues' || k === 'listCalendars') {
      const list = run.cvList || [];
      delete run.cvList;
      const want = values();
      const plan2 = { queue: [], filled: [], unchanged: [], missing: [], noValue: [] };
      for (const [key, name] of Object.entries(cfg.customValueNames)) {
        const value = S(want[key]);
        if (!value) { plan2.noValue.push(name); continue; }
        const cv = list.find(x => norm(x.name) === norm(name));
        if (!cv) plan2.missing.push(name);
        else if (S(cv.value) === value) plan2.unchanged.push(name);
        else plan2.queue.push({ id: cv.id, name: cv.name, value });
      }
      run.cv = plan2;
    }
    if (k === 'updateCustomValue') {
      const item = run.cv.queue.shift();
      if (!r.ok) { run.cv.failed = (run.cv.failed || []).concat([`${item.name} (${why(r)})`]); }
      else run.cv.filled.push(item.name);
    }
    if (k === 'listCustomValues' || k === 'listCalendars' || k === 'updateCustomValue') {
      const next = run.cv.queue[0];
      if (next) return ask('updateCustomValue', { locationId: loc(), token: run.token, id: next.id, body: { name: next.name, value: next.value } });
      const cv = run.cv;
      const summary = { filled: cv.filled, unchanged: cv.unchanged, missing: cv.missing, noValue: cv.noValue, failed: cv.failed || [], bookingLink: run.bookingLink || '' };
      const bookingMissing = cfg.customValueNames.bookingLink && !run.bookingLink;
      const gaps = [];
      if (cv.missing.length) gaps.push(`the sub-account has no custom value named ${cv.missing.map(n => `"${n}"`).join(', ')}`);
      if ((cv.failed || []).length) gaps.push(`these could not be saved: ${cv.failed.join(', ')}`);
      if (gaps.length || bookingMissing) return soft(summary, gaps.length ? gaps.join('; ') : `the booking link is missing: ${run.issues[run.issues.length - 1] || 'no calendar'}`);
      return done(summary);
    }
  }
  if (run.step === 'contact') {
    const id = r.ok && r.body && r.body.contact && r.body.contact.id;
    if (!id) return fail(r.ok ? 'the upsert answer had no contact ID' : why(r));
    // A returning client keeps the tag from the first onboarding. Adding it again fires no "tag added" event, and workflow 1
    // does not let a contact in twice, so the welcome email and the tasks would not start: say so instead.
    const hadTag = (r.body.contact.tags || []).some(t => norm(t) === norm(cfg.newClientTag));
    return done({ contactId: id, new: !!r.body.new, ...(hadTag ? { hadTag: true } : {}) });
  }
  if (run.step === 'opportunity') {
    if (k === 'findOpportunity') {
      if (!r.ok) return fail(why(r));
      const mine = ((r.body && r.body.opportunities) || []).filter(o => o.pipelineId === cfg.pipelineId && o.contactId === st.contact.contactId);
      const open = mine.find(o => o.status === 'open');
      const closed = mine.find(o => o.status === 'lost' || o.status === 'abandoned');
      if (open && open.pipelineStageId === cfg.stageId) return done({ opportunityId: open.id, action: 'kept' });
      const reuse = open || closed;
      if (reuse) { run.oppAction = open ? 'moved' : 'reopened'; return ask('updateOpportunity', { id: reuse.id, body: { pipelineStageId: cfg.stageId, status: 'open' } }); }
      const total = ctx.data.amount && ctx.data.amount.total;
      return ask('createOpportunity', { body: { pipelineId: cfg.pipelineId, locationId: cfg.homeLocationId, name: `${c.business}: ${plan.label} onboarding`.slice(0, 120),
        pipelineStageId: cfg.stageId, status: 'open', contactId: st.contact.contactId, ...(Number.isFinite(total) ? { monetaryValue: total / 100 } : {}) } });
    }
    if (k === 'updateOpportunity') {
      if (!r.ok) return fail(why(r));
      return done({ opportunityId: r.body.opportunity.id, action: run.oppAction });
    }
    if (k === 'createOpportunity') {
      if (r.ok && r.body && r.body.opportunity) return done({ opportunityId: r.body.opportunity.id, action: 'created' });
      if (r.retryable && run.tries < cfg.apiMaxAttempts) { run.tries++; await sleep(cfg.retryBaseSeconds * 2); return ask('findOpportunity', oppQuery()); }
      return fail(why(r), /duplicate/i.test(r.explain || '') ? 'The contact already has a won opportunity in this pipeline and the sub-account does not allow a second one. Add the opportunity by hand or turn on "Allow Multiple Opportunities per Contact"' : '');
    }
  }
  if (run.step === 'note') {
    if (k === 'findNotes') {
      if (!r.ok) return fail(why(r));
      const n = ((r.body && r.body.notes) || []).find(x => String(x.body || '').includes(marker));
      if (n) return done({ noteId: n.id, adopted: true });
      return ask('addNote', { contactId: st.contact.contactId, body: { body: noteText() } });
    }
    if (k === 'addNote') {
      if (r.ok && r.body && r.body.note) return done({ noteId: r.body.note.id, adopted: false });
      if (r.retryable && run.tries < cfg.apiMaxAttempts) { run.tries++; await sleep(cfg.retryBaseSeconds * 2); return ask('findNotes', { contactId: st.contact.contactId }); }
      return fail(why(r));
    }
  }
  if (run.step === 'tag') {
    if (!r.ok) return fail(why(r));
    return done({ tag: cfg.newClientTag });
  }
  if (run.step === 'slack') {
    if (!r.ok) return fail(why(r));
    return done({});
  }
  if (run.step === 'finishNote') {
    if (!r.ok) run.issues.push(`the "Onboarding finished" note did not reach Slack (${why(r)})`);
    run.step = null;
    return go('finish');
  }
}

function oppQuery() {
  return { query: { location_id: cfg.homeLocationId, contact_id: st.contact.contactId, pipeline_id: cfg.pipelineId, status: 'all', limit: '20' } };
}
function noteText() {
  const cv = st.customValues || {};
  return [
    `Onboarding started from a Stripe checkout ${marker}`,
    `Plan: ${plan.label} (${amountText()}), Stripe session ${ctx.data.sessionId}`,
    `Sub-account: ${c.business} (${loc()}) ${locUrl(loc())}`,
    `Admin user: ${c.name} <${c.email}> (${(st.user || {}).userId})`,
    cv.done ? `Custom values: ${(cv.filled || []).length} filled${(cv.unchanged || []).length ? `, ${cv.unchanged.length} already right` : ''}` : `Custom values: not finished, see Slack`,
  ].join('\n');
}
function slackText() {
  const cv = st.customValues || {};
  const todo = [];
  if (!cv.done) todo.push(`Custom values: ${cv.error || 'not filled'}. Set them by hand in the sub-account (Settings > Custom Values) or send a retry once fixed.`);
  const again = !!(st.tag && st.tag.alreadyThere);
  if (again) todo.push(`Welcome: the contact already had the tag ${cfg.newClientTag} from an earlier onboarding, so the onboarding workflow in GoHighLevel (welcome email, tasks) does not start again. Send the welcome email and create the tasks by hand.`);
  const opp = st.opportunity || {};
  const lines = [
    `${todo.length ? ':warning: *New client onboarded, with something to finish*' : ':tada: *New client onboarded*'}: ${slackSafe(c.business)} (${slackSafe(plan.label)} plan, ${amountText()})`,
    `Owner: ${slackSafe(c.name)} &lt;${slackSafe(c.email)}&gt;${c.phone ? ', ' + slackSafe(c.phone) : ''}`,
    `Sub-account: <${locUrl(loc())}|${slackSafe(c.business)}> ${st.subaccount.adopted ? '(an existing sub-account was found and used, none was created)' : `(created from the ${slackSafe(plan.label)} snapshot)`}, admin user ${st.user.adopted ? 'already there' : 'created'} for ${slackSafe(c.email)}`,
    `Custom values: ${cv.done ? `${(cv.filled || []).length} filled, ${(cv.unchanged || []).length} already right` : 'not finished'}${(cv.noValue || []).length ? ` (no value from the checkout for ${cv.noValue.map(slackSafe).join(', ')})` : ''}`,
    `Agency CRM: <${contactUrl(st.contact.contactId)}|contact> ${st.contact.new ? 'created' : 'updated'}, ${{ created: 'opportunity created in', kept: 'opportunity already in', moved: 'opportunity moved to', reopened: 'lost opportunity reopened in' }[opp.action] || 'opportunity in'} Onboarding, ${again ? `tag ${slackSafe(cfg.newClientTag)} was already on the contact (the welcome email and the tasks do not start again)` : `tag ${slackSafe(cfg.newClientTag)} added (the welcome email and the onboarding tasks start now)`}`,
    `Stripe event ${ctx.eventId}, session ${slackSafe(ctx.data.sessionId)}`,
  ];
  if (todo.length) lines.push('To finish: ' + todo.map(slackSafe).join(' '));
  return lines.join('\n');
}

// ---------------------------------------------------------------- start the next step, or a phase after a save
if (run.step === 'subaccount' && run.phase === 'create') {
  return ask('createLocation', { body: {
    name: c.business, companyId: cfg.companyId, snapshotId: plan.snapshotId, timezone: cfg.clientTimezone,
    ...(c.phone ? { phone: c.phone } : {}), ...(c.address1 ? { address: c.address1 } : {}), ...(c.city ? { city: c.city } : {}),
    ...(c.state ? { state: c.state } : {}), ...(c.postalCode ? { postalCode: c.postalCode } : {}), ...(/^[A-Z]{2}$/.test(c.country) ? { country: c.country } : {}),
    ...(c.website ? { website: c.website } : {}),
    prospectInfo: { firstName: c.firstName, lastName: c.lastName || '-', email: c.email },
  } });
}
const next = ORDER.find(s => !(st[s] && st[s].done) && !run.softFailed.includes(s));
if (!next) {
  // A retry that finished what an earlier run left open (after its Slack summary) tells the channel it is done now.
  if (ctx.slackWasDone && !run.noteSent && ORDER.every(s => st[s] && st[s].done)) {
    run.noteSent = true; run.step = 'finishNote';
    return ask('slack', { body: { text: `:white_check_mark: *Onboarding finished*: ${slackSafe(c.business)} (${slackSafe(plan.label)} plan). The items the earlier run left open are done now.` } });
  }
  return go('finish');
}
run.step = next; run.tries = 1; run.waited = 0;
if (next === 'subaccount') {
  if (ctx.retryOptions.subAccountId) return ask('getLocation', { locationId: ctx.retryOptions.subAccountId });
  return ask('findLocation', { query: { companyId: cfg.companyId, email: c.email, limit: '100' } });
}
if (next === 'user') return ask('findUser', { query: { companyId: cfg.companyId, query: c.email, limit: '25' } });
if (next === 'customValues') return ask('snapshotStatus', { snapshotId: plan.snapshotId, locationId: loc(), query: { companyId: cfg.companyId } });
if (next === 'contact') {
  const body = { locationId: cfg.homeLocationId, firstName: c.firstName, lastName: c.lastName, name: c.name, email: c.email, companyName: c.business, source: 'Stripe onboarding checkout' };
  for (const [k, v] of Object.entries({ phone: c.phone, address1: c.address1, city: c.city, state: c.state, postalCode: c.postalCode, country: c.country, website: c.website })) if (v) body[k] = v;
  if (!body.lastName) delete body.lastName;
  return ask('upsertContact', { body });
}
if (next === 'opportunity') return ask('findOpportunity', oppQuery());
if (next === 'note') return ask('findNotes', { contactId: st.contact.contactId });
if (next === 'tag') {
  if (st.contact.hadTag) return done({ tag: cfg.newClientTag, alreadyThere: true });
  return ask('addTag', { contactId: st.contact.contactId, body: { tags: [cfg.newClientTag] } });
}
return ask('slack', { body: { text: slackText() } });

// n8n error objects (from an error output) carry message, description and sometimes httpCode
const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e.slice(0, 300);
  const parts = [e.httpCode, e.message, e.description].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(String);
  return [...new Set(parts)].join(' - ').replace(/\s+/g, ' ').slice(0, 300);
};

// Turns one answer into ok, try again, or failed. 429 waits for Retry-After (or GHL_RATE_LIMIT_WAIT_SECONDS) and
// repeats the call: nothing was done. 5xx and dropped connections back off exponentially; for a create they go back to
// the Step Engine, which looks the record up before creating it again. 401, 403, 400 and 422 are not retried.
const cfg = $('Load Settings').first().json.cfg;
const ctx = JSON.parse(JSON.stringify($('Build Call').first().json));
const call = ctx.call;
const res = $input.first().json;
const sleep = s => new Promise(r => setTimeout(r, s * 1000));
const cap = s => String(s).charAt(0).toUpperCase() + String(s).slice(1);
const UNSAFE = ['createLocation', 'createUser', 'createOpportunity', 'addNote'];
const WHO = {
  agency: 'the HighLevel agency credential in n8n (the OAuth app installed on your agency)',
  location: 'the sub-account token from /oauth/locationToken',
  home: "GHL_HOME_TOKEN (the Private Integration token of your agency's own sub-account)",
};
const who = ['listCalendars', 'listCustomValues', 'updateCustomValue'].includes(call.kind) ? 'location'
  : ['upsertContact', 'findOpportunity', 'createOpportunity', 'updateOpportunity', 'findNotes', 'addNote', 'addTag'].includes(call.kind) ? 'home'
  : call.kind === 'slack' ? 'slack' : 'agency';
const SCOPE = {
  findLocation: 'locations.readonly', listLocations: 'locations.readonly', getLocation: 'locations.readonly', createLocation: 'locations.write',
  snapshotStatus: 'snapshots.readonly', appInstalled: 'oauth.readonly', findUser: 'users.readonly', createUser: 'users.write', locationToken: 'oauth.write',
  listCalendars: 'calendars.readonly', listCustomValues: 'locations/customValues.readonly', updateCustomValue: 'locations/customValues.write',
  upsertContact: 'contacts.write', findOpportunity: 'opportunities.readonly', createOpportunity: 'opportunities.write',
  updateOpportunity: 'opportunities.write', findNotes: 'contacts.readonly', addNote: 'contacts.write', addTag: 'contacts.write',
};
let status = Number(res.statusCode) || 0;
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const conn = res.error && !res.statusCode;
const msgOf = b => {
  if (!b) return '';
  if (typeof b === 'string') return b.slice(0, 200);
  const m = b.message ?? b.error ?? '';
  return (Array.isArray(m) ? m.join('; ') : String(m)).slice(0, 300);
};
let ok, kind, message;
if (who === 'slack') {
  ok = !conn && status >= 200 && status < 300;
  kind = ok ? 'ok' : conn || status >= 500 || status === 429 ? 'unavailable' : 'request';
  message = conn ? errText(res.error) : msgOf(body);
} else {
  ok = !conn && status >= 200 && status < 300 && body && typeof body === 'object';
  message = conn ? errText(res.error) : msgOf(body);
  kind = ok ? 'ok' : conn ? 'unavailable' : status === 429 ? 'throttled' : status >= 500 ? 'unavailable'
    : status === 401 && /scope/i.test(message) ? 'scope' : status === 401 ? 'auth' : status === 403 ? 'forbidden' : 'request';
}
if (ok) return [{ json: { ...ctx, route: 'engine', reply: { ok: true, status, body } } }];
const attempt = Number(call.attempt) || 1;
const retryable = kind === 'throttled' || kind === 'unavailable';
// A create is tried again by the Step Engine (after a lookup), so its count of tries lives there.
const tries = UNSAFE.includes(call.kind) && kind !== 'throttled' ? (Number((ctx.run || {}).tries) || 1) : attempt;
message = String(message).replace(/[.\s]+$/, '');
const name = who === 'slack' ? 'Slack' : 'GoHighLevel';
const explain = {
  throttled: `${name} still answered 429 (rate limit) after ${tries} tries`,
  unavailable: `${name} did not answer${status ? ' (' + status + ')' : ''} after ${tries} tries`,
  auth: `GoHighLevel refused the token (401). Check ${WHO[who]}`,
  scope: `GoHighLevel says the token may not do this (401). ${cap(WHO[who])} needs the ${SCOPE[call.kind]} scope`,
  forbidden: `GoHighLevel refused access (403). ${cap(WHO[who])} cannot reach this ${who === 'home' ? 'sub-account (check GHL_HOME_LOCATION_ID)' : 'record'}`,
  request: `${name} rejected the request (${status})`,
}[kind] + (message ? `. It said: ${message}` : '');
if (retryable && attempt < cfg.apiMaxAttempts && (kind === 'throttled' || !UNSAFE.includes(call.kind))) {
  const ra = Number((res.headers || {})['retry-after']);
  await sleep(kind === 'throttled' ? Math.min(120, Number.isFinite(ra) && ra > 0 ? ra : cfg.rateLimitWait) : Math.min(60, cfg.retryBaseSeconds * 2 ** (attempt - 1)));
  ctx.call = { ...call, attempt: attempt + 1 };
  return [{ json: { ...ctx, route: 'again' } }];
}
return [{ json: { ...ctx, route: 'engine', reply: { ok: false, status, kind, retryable, explain: explain.replace(/\s+/g, ' ').slice(0, 600), body: body && typeof body === 'object' ? body : null } } }];

// n8n error objects (from an error output) carry message, description and sometimes httpCode
const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e.slice(0, 300);
  const parts = [e.httpCode, e.message, e.description].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(String);
  return [...new Set(parts)].join(' - ').replace(/\s+/g, ' ').slice(0, 300);
};

// Continues with the next step only if the ledger took the progress. If it did not, the run stops here: going on
// without a record of what was created could lead a later retry to create it again.
const ctx = $('Step Engine').first().json;
const saved = $('Ledger: Save Progress').first().json;
if (!saved || !saved.key) {
  const run = { ...ctx.run, failure: { step: ctx.run.step || 'ledger', reason: `the ledger could not save the progress${saved && saved.error ? ': ' + errText(saved.error) : ''}`, hint: 'Check the n8n data table, then send the retry' } };
  return [{ json: { ...ctx, run, route: 'finish' } }];
}
return [{ json: { ...ctx, route: 'next' } }];

const ORDER = ['subaccount', 'user', 'customValues', 'contact', 'opportunity', 'note', 'tag', 'slack'];
const LABEL = {
  subaccount: 'create the sub-account from the snapshot', user: 'create the admin user', customValues: 'fill the custom values',
  contact: 'add the client to the agency CRM', opportunity: 'put the opportunity in the Onboarding stage', note: 'add the onboarding note',
  tag: 'add the new client tag', slack: 'post the Slack summary',
};

const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Records the result and, when anything is open, writes the alert: what exists now (with IDs), what is still to do
// (with the values a person needs to do it by hand), and how to let the workflow finish it.
const cfg = $('Load Settings').first().json.cfg;
const ctx = $input.first().json;
const st = ctx.steps, run = ctx.run, c = ctx.client, plan = ctx.plan;
const all = ORDER.every(s => st[s] && st[s].done);
const cv = st.customValues || {};
const values = {
  businessName: c.business, businessPhone: c.phone, businessEmail: c.email, businessAddress: c.address1, businessCity: c.city,
  businessState: c.state, businessPostalCode: c.postalCode, businessCountry: c.country, businessWebsite: c.website,
  ownerFirstName: c.firstName, ownerName: c.name, bookingLink: run.bookingLink || cv.bookingLink || `the booking link of the "${cfg.bookingCalendar}" calendar`,
};
const filled = new Set([...(cv.filled || []), ...(cv.unchanged || [])]);
const openValues = Object.entries(cfg.customValueNames).filter(([k, name]) => values[k] && !filled.has(name))
  .map(([k, name]) => `${name} = ${values[k]}${(cv.missing || []).includes(name) ? ' (create it, the snapshot does not have it)' : ''}`);
const have = [];
if (st.subaccount && st.subaccount.locationId) have.push(`sub-account "${st.subaccount.name || c.business}" (ID ${st.subaccount.locationId})${st.subaccount.adopted ? ', found and used as it was' : ''}`);
if (st.user && st.user.done) have.push(`admin user ${c.email} (ID ${st.user.userId})`);
if (cv.done) have.push('every custom value');
else if (filled.size) have.push(`custom values ${[...filled].join(', ')}`);
if (st.contact && st.contact.done) have.push(`contact in the agency sub-account (ID ${st.contact.contactId})`);
if (st.opportunity && st.opportunity.done) have.push(`opportunity in the Onboarding stage (ID ${st.opportunity.opportunityId})`);
if (st.note && st.note.done) have.push('onboarding note');
if (st.tag && st.tag.done) have.push(st.tag.alreadyThere ? `tag ${cfg.newClientTag} (it was already on the contact, so the onboarding workflow did not start again)` : `tag ${cfg.newClientTag}, so the onboarding workflow has started`);
if (st.slack && st.slack.done) have.push('Slack summary');
const TODO = {
  subaccount: `create the sub-account "${c.business}" from the ${plan.label} snapshot (${plan.snapshotId})`,
  user: `add ${c.name} <${c.email}> as an admin user of that sub-account`,
  customValues: openValues.length ? `set these custom values in the sub-account (Settings > Custom Values): ${openValues.join('; ')}` : '',
  contact: `add ${c.name} <${c.email}> of ${c.business} as a contact in the agency sub-account`,
  opportunity: 'put an opportunity for the client in the Onboarding stage',
  note: 'add a note with the plan and the sub-account to the contact',
  tag: `add the tag ${cfg.newClientTag} to the contact (it starts the welcome email and the onboarding tasks)`,
  slack: 'tell the team in Slack',
};
const todo = ORDER.filter(s => !(st[s] && st[s].done)).map(s => TODO[s]).filter(Boolean);
let stopMessage = '';
if (!all) {
  const f = run.failure;
  const parts = [];
  if (f) parts.push(`It stopped at "${LABEL[f.step] || f.step}": ${f.reason}.${f.hint ? ' ' + f.hint + '.' : ''}`);
  if (run.issues.length) parts.push(`${f ? 'Also' : 'Open'}: ${run.issues.join('; ')}.`);
  stopMessage = slackSafe(`Onboarding of ${c.business} (${c.email}, ${plan.label} plan, Stripe event ${ctx.eventId}) is not finished. ${parts.join(' ')}`
    + ` Done: ${have.join('; ') || 'nothing yet'}. Still to do: ${todo.join('; ')}.`
    + ` To let the workflow finish it, fix the cause and send the retry (POST /webhook/ghl-onboarding-retry with the X-Run-Secret header and {"eventId": "${ctx.eventId}"}); it continues from the first open step and never creates a second sub-account or user. Or do the open items by hand.`);
}
const ids = {
  locationId: (st.subaccount || {}).locationId || '', userId: (st.user || {}).userId || '', contactId: (st.contact || {}).contactId || '',
  opportunityId: (st.opportunity || {}).opportunityId || '',
};
return [{ json: { eventId: ctx.eventId, status: all ? 'done' : 'failed', steps: JSON.stringify(st), ...ids,
  note: all ? `Done in run ${$execution.id}` : `Not finished (run ${$execution.id}): ${(run.failure || {}).reason || run.issues.join('; ')}`.slice(0, 900), stopMessage } }];

// n8n error objects (from an error output) carry message, description and sometimes httpCode
const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e.slice(0, 300);
  const parts = [e.httpCode, e.message, e.description].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(String);
  return [...new Set(parts)].join(' - ').replace(/\s+/g, ' ').slice(0, 300);
};

// Every run that took the lock ends here; the lock is released next, whatever happened.
if ($('Finish Onboarding').isExecuted) {
  const f = $('Finish Onboarding').first().json;
  const saved = $('Ledger: Save Result').first().json;
  let msg = f.stopMessage;
  if (!saved || !saved.key) msg = `${msg ? msg + ' ' : ''}The ledger could not record the result${saved && saved.error ? ' (' + errText(saved.error) + ')' : ''}: set status "${f.status}" on row ${f.eventId} in the data table by hand.`;
  return [{ json: { failed: !!msg, stop: 'onboarding', stopMessage: msg } }];
}
const p = $('Plan Event').first().json;
if (p.route === 'needs-review') {
  const c = (p.data || {}).client || {};
  const text = `A paid checkout needs a person before onboarding can start (Stripe event ${p.eventId}, ${c.business || 'no business name'}, ${c.email || 'no email'}): ${p.problems.join('; ')}. Nothing was created. Fix it (for example add the plan to PLAN_SNAPSHOTS), then send the retry (POST /webhook/ghl-onboarding-retry with {"eventId": "${p.eventId}"}).`;
  return [{ json: { failed: true, stop: 'review', stopMessage: text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') } }];
}
return [{ json: { failed: false } }];

// Constant time comparison: the loop always runs over the longer string and never stops early.
const sameText = (a, b) => {
  a = String(a ?? ''); b = String(b ?? '');
  let d = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) d |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return d === 0;
};

// The native workflows in the agency sub-account call this with a Custom Webhook action: header X-Onboarding-Secret,
// form-style key and value pairs (or JSON) event, contactId, email, company, name, appointmentStart. The free standard
// Webhook action cannot set headers, so customData.secret (and customData.event) are accepted as well.
const req = $('GHL Status').first().json;
const b = req.body && typeof req.body === 'object' ? req.body : {};
const cd = b.customData && typeof b.customData === 'object' ? b.customData : {};
const S = v => String(v ?? '').trim();
const given = S((req.headers || {})['x-onboarding-secret'] || cd.secret);
if (!given || !sameText(given, S($env.GHL_STATUS_SECRET))) {
  return [{ json: { route: 'refused', stop: 'secret', respond: { status: 401, body: { ok: false, error: 'unauthorized' } },
    stopMessage: 'Refused a status call from GoHighLevel: wrong or missing X-Onboarding-Secret header. Nothing was changed.' } }];
}
const event = S(b.event || cd.event).toLowerCase();
const contactId = S(b.contactId || b.contact_id || cd.contactId);
const email = S(b.email || cd.email).toLowerCase();
if (!['kickoff_booked', 'kickoff_not_booked'].includes(event) || !/^[A-Za-z0-9]{4,64}$/.test(contactId)) {
  return [{ json: { route: 'refused', stop: 'status-call', respond: { status: 400, body: { ok: false, error: 'send event (kickoff_booked or kickoff_not_booked) and contactId' } },
    stopMessage: `A status call from GoHighLevel was missing its event or contact ID (event "${event.slice(0, 40)}"). Check the body of the Custom Webhook action in the native workflow.` } }];
}
return [{ json: { route: 'ok', event, contactId, email, company: S(b.company || cd.company).slice(0, 120), name: S(b.name || cd.name || b.full_name).slice(0, 120),
  appointmentStart: S(b.appointmentStart || cd.appointmentStart).slice(0, 80), respond: { status: 200, body: { ok: true } } } }];

const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// One Slack note per status call, and the kickoff column of the client's ledger row.
const call = $('Check Status Call').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.key && r.key !== '__run_lock__' && r.status !== 'lock');
const row = rows.find(r => r.contactId === call.contactId) || rows.find(r => call.email && r.email === call.email) || null;
const who = row ? row.business : (call.company || call.name || call.email || `contact ${call.contactId}`);
const at = call.appointmentStart ? ` for ${call.appointmentStart}` : '';
const text = call.event === 'kickoff_booked'
  ? `:calendar: *Kickoff call booked*: ${slackSafe(who)}${slackSafe(at)}.`
  : `:hourglass_flowing_sand: *Kickoff call not booked yet*: ${slackSafe(who)}${call.email ? ' (' + slackSafe(call.email) + ')' : ''}. The onboarding workflow reminded the account manager in GoHighLevel too.`;
const note = row ? '' : ' (not in the onboarding ledger, so it was probably onboarded by hand)';
return [{ json: { key: row ? row.key : '__none__', kickoff: call.event === 'kickoff_booked' ? `booked${at} (${new Date().toISOString()})` : `not booked, reminder sent ${new Date().toISOString()}`,
  slack: { text: text + note } } }];

// n8n error objects (from an error output) carry message, description and sometimes httpCode
const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e.slice(0, 300);
  const parts = [e.httpCode, e.message, e.description].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(String);
  return [...new Set(parts)].join(' - ').replace(/\s+/g, ' ').slice(0, 300);
};

// Slack is called with n8n's own retry (3 tries); a failure leaves through the error output with an error object.
const res = $input.first().json;
const rec = $('Record Status').first().json;
return [{ json: { failed: !!res.error, stopMessage: res.error ? `Slack did not take the kickoff note (${errText(res.error)}). The note was: ${rec.slack.text}` : '' } }];

// Stripe already got its 200 for these events, so nobody would notice an onboarding that n8n never finished (for
// example after a restart in the middle of a run: the error workflow does not run then). A row still "in_progress"
// with no change for STUCK_CHECK_MINUTES, while no run holds the lock, is such a run.
const cfg = $('Load Settings').first().json.cfg;
const rows = $input.all().map(i => i.json).filter(r => r && r.key);
const lock = rows.find(r => r.key === '__run_lock__');
if (lock && Number(lock.attempts) > Date.now()) return [];
const cutoff = Date.now() - cfg.stuckMinutes * 60000;
return rows.filter(r => r.key !== '__run_lock__' && r.status === 'in_progress' && (Date.parse(r.changedAt) || 0) < cutoff)
  .map(r => ({ json: { key: r.key, changedAt: r.changedAt, business: r.business, email: r.email, steps: r.steps } }));

const ORDER = ['subaccount', 'user', 'customValues', 'contact', 'opportunity', 'note', 'tag', 'slack'];
const LABEL = {
  subaccount: 'create the sub-account from the snapshot', user: 'create the admin user', customValues: 'fill the custom values',
  contact: 'add the client to the agency CRM', opportunity: 'put the opportunity in the Onboarding stage', note: 'add the onboarding note',
  tag: 'add the new client tag', slack: 'post the Slack summary',
};

const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// One alert for every onboarding found. Each is marked failed, so it is reported once and the Retry webhook can continue it.
const found = $('Check Unfinished').all().map(i => i.json);
const marked = new Set($input.all().map(i => i.json).filter(r => r && r.key).map(r => r.key));
const parse = t => { try { return JSON.parse(t || '{}') || {}; } catch (e) { return {}; } };
const list = found.filter(r => marked.has(r.key)).map(r => {
  const st = parse(r.steps);
  const done = ORDER.filter(s => st[s] && st[s].done).map(s => LABEL[s]);
  const minutes = Math.round((Date.now() - (Date.parse(r.changedAt) || 0)) / 60000);
  return `${r.business} (${r.email}, Stripe event ${r.key}; done so far: ${done.join(', ') || 'nothing'}; no progress for ${minutes} minutes)`;
});
if (!list.length) return [];
return [{ json: { stopMessage: slackSafe(`${list.length} onboarding${list.length > 1 ? 's' : ''} stopped without finishing and without an alert, most likely because n8n restarted in the middle of the run: ${list.join('; ')}. Nothing is lost: the ledger has every finished step and its IDs. ${list.length > 1 ? 'They are' : 'It is'} marked failed now. Send the retry for each (POST /webhook/ghl-onboarding-retry with the X-Run-Secret header and {"eventId": "..."}); it continues from the first open step.`) } }];
